Almost! There are **3 things to fix**, but your `skip` and `limit` handling is correct.

### 1. Your JSON ternaries are backwards

You wrote:

```js
var where = req.query.where === undefined ? JSON.parse(req.query.where) : {}
```

This tries to parse `undefined` when the parameter is missing.

It should be:

```js
var where = req.query.where === undefined ? {} : JSON.parse(req.query.where);
var sort = req.query.sort === undefined ? {} : JSON.parse(req.query.sort);
var select = req.query.select === undefined ? {} : JSON.parse(req.query.select);
```

### 2. Make the function `async`

You'll eventually execute Mongoose queries using `await`, so change your function declaration to:

```js
async function handleGet(Model, req, res, defaultLimit) {
```

### 3. Implement your `catch` block

You need to distinguish invalid JSON from unexpected server errors:

```js
catch (e) {
    if (e instanceof SyntaxError) {
        return res.status(400).json({
            message: "Invalid JSON query parameter",
            data: null
        });
    }

    return res.status(500).json({
        message: "Internal server error",
        data: null
    });
}
```

### What you've done correctly

- `skip` defaults to `0`.
- `limit` defaults to `defaultLimit`.
- You correctly check that `skip` and `limit` are nonnegative integers.
- You correctly allow `limit === null` for unlimited user results.

**Next:** Once you've corrected these, we'll add the `count` parameter and construct the actual Mongoose query using `where`, `sort`, `select`, `skip`, and `limit`.

async function handleGet(Model, req, res, defaultLimit) {
        try {
            var where = req.query.where === undefined ? {} : JSON.parse(req.query.where);
            var sort = req.query.sort === undefined ? {} : JSON.parse(req.query.sort);
            var select = req.query.select === undefined ? {} : JSON.parse(req.query.select);
            var skip = req.query.skip === undefined ? 0 : Number(req.query.skip);
            var limit = req.query.limit === undefined ? defaultLimit : Number(req.query.limit);
            if ( !Number.isInteger(skip) || skip < 0 || (limit !== null && (!Number.isInteger(limit) || limit < 0))) {
                return res.status(400).json({
                    message: "Invalid query parameters",
                    data: null
                });
            }

            var count = req.query.count === "true";
            if (count) {
                var cnt = Model.countDocuments(where)
                return res.status(200).json({
                    message: "OK",
                    data: cnt
                })
            }

            var q = Model.find(where)
            q.sort(sort).select(select).skip(skip);
            if (limit !== null) {
                q.limit(limit)
            }

            var res = await q
            return res.status(200).json({
                message: "OK",
                data: res
            })

        }

        catch (e) {
            if (e instanceof SyntaxError) {
                return res.status(400).json({
                    message: "Invalid JSON query parameter",
                    data: null
                });
            }

            return res.status(500).json({
                message: "Internal server error",
                data: null
            });
        }
    }

